// This file is generated by AI.

// config.txt 解析与改写的断言。
//
// 这里钉住的是与语言服务 (crates/webgal-language-core/src/resource/config.rs) 一致的
// 那几条规则: 首个 `:` 分隔键值, 行内首个 `;` 之后是注释, 同名配置取值时"后者胜"。
// 侧栏摘要读的就是这份结果, 规则一旦分叉, 界面显示的名字会和服务端诊断打架。

import { describe, expect, it } from 'vitest';

import {
  gameConfigSummary,
  gameConfigValue,
  parseGameConfigText,
  setGameConfigValue,
  setGameConfigValues,
} from '../src/lib/gameConfig';

describe('parseGameConfigText', () => {
  it('按行解析键值, 跳过空行与纯注释行', () => {
    const entries = parseGameConfigText('Game_name:星海叙事;\n\n; 这是注释\nGame_key:abc;\n');
    expect(entries).toEqual([
      { name: 'Game_name', value: '星海叙事', comment: '' },
      { name: 'Game_key', value: 'abc', comment: '' },
    ]);
  });

  it('保留行内注释', () => {
    const entries = parseGameConfigText('Title_img:title.png; 标题背景图\n');
    expect(entries[0]).toEqual({ name: 'Title_img', value: 'title.png', comment: '标题背景图' });
  });

  it('缺少结尾分号也能解析, 缺少冒号则整行忽略', () => {
    const entries = parseGameConfigText('Game_name:Demo\n没有冒号的一行\n');
    expect(entries).toEqual([{ name: 'Game_name', value: 'Demo', comment: '' }]);
  });

  it('值为空的配置不算配置项 (与 is_config 一致)', () => {
    expect(parseGameConfigText('Game_name:;\n')).toEqual([]);
  });

  it('CRLF 换行同样解析', () => {
    expect(parseGameConfigText('Game_name:A;\r\nGame_key:B;\r\n')).toHaveLength(2);
  });

  it('同名配置保留两条 (取值时后者胜)', () => {
    const entries = parseGameConfigText('Game_name:旧;\nGame_name:新;\n');
    expect(entries).toHaveLength(2);
    expect(gameConfigValue(entries, 'Game_name')).toBe('新');
  });
});

describe('gameConfigSummary', () => {
  it('汇总侧栏需要的字段', () => {
    const entries = parseGameConfigText(
      'Game_name:星海叙事;\nGame_key:key-1;\nDescription:一个测试项目;\nTitle_img:cover.png;\nTitle_bgm:bgm.ogg;\nGame_Logo:logo.png;\n'
    );
    expect(gameConfigSummary(entries)).toEqual({
      name: '星海叙事',
      gameKey: 'key-1',
      description: '一个测试项目',
      titleImg: 'cover.png',
      titleBgm: 'bgm.ogg',
      logo: 'logo.png',
    });
  });

  it('缺字段时给出空串而不是 undefined', () => {
    expect(gameConfigSummary([])).toEqual({
      name: '',
      gameKey: '',
      description: '',
      titleImg: '',
      titleBgm: '',
      logo: '',
    });
  });
});

describe('setGameConfigValue', () => {
  it('改写已有配置并保留行内注释', () => {
    const next = setGameConfigValue('Game_name:旧; 游戏名称\n', 'Game_name', '新');
    expect(next).toBe('Game_name:新; 游戏名称\n');
  });

  it('配置不存在时追加到末尾', () => {
    const next = setGameConfigValue('Game_name:旧;\n', 'Game_key', 'key-1');
    expect(next).toBe('Game_name:旧;\nGame_key:key-1;\n');
  });

  it('结尾没有换行的文件不会在追加后被粘住', () => {
    const next = setGameConfigValue('Game_name:旧;', 'Game_key', 'key-1');
    expect(next).toBe('Game_name:旧;\nGame_key:key-1;');
  });

  it('空文件直接生成一行', () => {
    expect(setGameConfigValue('', 'Game_name', '新')).toBe('Game_name:新;');
  });

  it('只改写最后一条同名配置', () => {
    const next = setGameConfigValue('Game_name:一;\nGame_name:二;\n', 'Game_name', '三');
    expect(next).toBe('Game_name:一;\nGame_name:三;\n');
  });

  it('一次改写多条 (新建项目写名称与识别码)', () => {
    const next = setGameConfigValues('Game_name:旧;\nDescription:简介;\n', {
      Game_name: '新',
      Game_key: 'key-1',
    });
    expect(next).toBe('Game_name:新;\nDescription:简介;\nGame_key:key-1;\n');
  });
});
